import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set block.timestamp to 100 initially
        vm.warp(100);
        // Fund the caller
        address caller = address(0x1234);
        vm.deal(caller, 10 ether);

        // First call: succeeds in both versions, sets pastBlockTime = 100 (reference) or 101 (buggy)
        vm.prank(caller);
        (bool success1, ) = address(c).call{value: 10 ether}("");
        // For the reference, pastBlockTime becomes 100; for buggy, 101

        // Warp to exactly the same timestamp (100) — so reference requires block.timestamp > pastBlockTime fails (100 > 100 is false)
        // Buggy contract still works because it checks 100 > 101? Actually buggy pastBlockTime=101, so 100 > 101 is also false => both revert.
        // To trigger a difference, we need buggy's pastBlockTime to be 100 (so that block.timestamp = 100 fails for reference but passes for buggy? No, buggy sets +1, so pastBlockTime is larger.)
        // Let's re-think: after first call reference pastBlockTime=100, buggy pastBlockTime=101.
        // Now set block.timestamp = 101
        vm.warp(101);
        // For reference: require(101 > 100) passes; sets pastBlockTime=101
        // For buggy: require(101 > 101) fails because pastBlockTime=101, so buggy reverts.
        // That's a revert difference: reference succeeds, buggy reverts.
        vm.prank(caller);
        (bool success2, ) = address(c).call{value: 10 ether}("");
        // success2 true for reference, false for buggy

        assertTrue(success2 == true);
