// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set initial pastBlockTime to some value
        vm.warp(100);
        vm.deal(address(this), 10 ether);
        c.fallback{value: 10 ether}();
        // pastBlockTime is now 100

        // Now warp to same timestamp (100) to trigger the edge case
        vm.warp(100);
        vm.deal(address(this), 10 ether);

        // The call should revert in reference but succeed in buggy
        bool ok;
        try c.fallback{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference reverts (ok == false), buggy succeeds (ok == true)
        // So we assert ok == false on reference
        assertTrue(!ok);
    }
}
